#tajemnice{pozycja:względna;przepełnienie:ukryta}
    #mysteries .wrap{position:relative;z-index:3}
    .myst-filterbar{display:flex;flex-wrap:wrap;gap:20px 28px;align-items:flex-end;margin-bottom:14px}
    .myst-filter-group{display:flex;flex-direction:column;gap:9px;min-width:0}
    .myst-filter-label{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{display:flex;flex-wrap:wrap;gap:8px}
    .myst-chip{
      display:inline-flex;align-items:center;gap:8px;kursor:wskaźnik;
      dopełnienie: 9px 15px;promień obramowania: 999px;
      rodzina czcionek: „Space Mono”, ui-monospace, monospace; rozmiar czcionki: 11 pikseli;
      odstępy między literami: .14em; transformacja tekstu: wielkie litery; kolor: #f4e3d7;
      tło: rgba (20,7,44,.72); obramowanie: 1 piksel stały rgba (255,45,124,.3);
      przejście: łatwość transformacji 0,15 s, łatwość cienia pudełkowego 0,2 s, łatwość koloru obramowania 0,2 s;
    }
    .myst-chip:hover{transform:translateY(-1px);border-color:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.active{
      tło:var(--vi-grad-sunset,linear-gradient(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      kolor:var(--vi-ink,#33051c);kolor-obramowania:przezroczysty;grubość czcionki:700;
      box-shadow:0 8px 22px -8px rgba(255,45,124,.65);
    }
    .myst-chip .myst-dot{width:8px;height:8px;border-radius:99px;flex:0 0 auto}
    .myst-chip.active .myst-dot{outline:1px solid rgba(51,5,28,.4)}
    .myst-dot--resolved{tło:liniowy-gradient(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{tło:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{tło:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--all{tło:#f4e3d7}
    .myst-chip mały{
      rozmiar czcionki: 10 pikseli; dopełnienie: 2 piksele 7 pikseli; promień obramowania: 99 pikseli; odstępy między literami: .08em;
      tło: rgba(11,13,42,.55);kolor:dziedzicz;obramowanie:1px pełne rgba(255,255,255,.18);
    }
    .myst-chip.active small{background:rgba(51,5,28,.22);border-color:rgba(51,5,28,.3)}
    .myst-select{
      wygląd: brak; - wygląd-webkit: brak; kursor: wskaźnik; minimalna szerokość: 220 pikseli;
      dopełnienie: 10 pikseli 38 pikseli 10 pikseli 14 pikseli;promień obramowania: 10 pikseli;
      rodzina czcionek: „Space Mono”, ui-monospace, monospace; rozmiar czcionki: 12 pikseli; odstępy między literami: .06 em;
      kolor:#fff5ec;tło:rgba(20,7,44,.72);obramowanie:1px pełny rgba(255,45,124,.3);
      obraz tła:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' szerokość='12' wysokość='8' viewBox='0 0 12 8'><ścieżka d='M1 1l5 5 5-5' fill='none' Stroke='%23ff2d7c' szerokość obrysu='2' obrys-linecap='okrągły'/></svg>");
      powtórzenie tła: brak powtórzeń; pozycja tła: prawy środek 14px;
    }
    .myst-select:focus{outline:none;border-color:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    .myst-select opcja{tło:#0b0d2a;kolor:#fff5ec}
    .myst-status-desc{
      margines: 0 0 18 pikseli; maksymalna szerokość: 760 pikseli; kolor: # d9c3d2; rozmiar czcionki: 14 pikseli; wysokość linii: 1,6;
      obramowanie po lewej: 3px pełne rgba (255,45,124,.55); dopełnienie po lewej stronie: 14px;
    }
    .myst-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px;align-items:start}
    .myst-card{display:flex;flex-direction:column;gap:0;padding:22px 22px 18px}
    .myst-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:wielkie litery}
    .myst-stamp{transform:rotate(-2deg);rozmiar-czcionki:10px;odstępy-liter:.2em;wypełnienie:6px 13px}
    .myst-stamp--rozwiązany{
      tło: gradient liniowy (90 stopni, var (--vi-gold, #ffd166), #7ee08c);
      kolor:var(--vi-ink,#33051c);box-shadow:0 8px 22px -8px rgba(255,209,102,.7),0 0 20px rgba(126,224,140,.25);
    }
    .myst-stamp--open{color:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--legend{
      kolor:#cfa9ff;box-shadow:0 0 22px rgba(123,47,247,.45);
      tło:
        gradient liniowy(rgba(26,9,54,.9),rgba(26,9,54,.9)) padding-box,
        gradient-liniowy(90deg,var(--vi-fioletowy,#7b2ff7),var(--vi-pink-2,#f152ff)) border-box;
    }
    .myst-game-chip{
      display:inline-flex;align-items:center;gap:6px;margin-bottom:10px;
      rodzina czcionek: „Space Mono”, ui-monospace, monospace; rozmiar czcionki: 10 pikseli;
      odstępy między literami: .18em; transformacja tekstu: wielkie litery; kolor: var(--vi-gold,#ffd166);
    }
    .myst-game-chip::before{content:"";width:14px;height:1px;background:var(--vi-gold,#ffd166);opacity:.7}
    .myst-card h3{margines: 0 0 10px;rozmiar czcionki:20px;wysokość linii:1,25;kolor:#fff5ec}
    .myst-desc{margin: 0; kolor: # d9c8d4; rozmiar czcionki: 14 pikseli; wysokość linii: 1,62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px przerywana rgba(255,45,124,.35)}
    .myst-evidence-label{
      display:flex;align-items:center;gap:8px;margin:16px 0 4px;
      rodzina czcionek: „Space Mono”, ui-monospace, monospace; rozmiar czcionki: 10 pikseli;
      odstępy między literami: .26em; transformacja tekstu: wielkie litery; kolor: #ff9ec4;
    }
    .myst-evidence-label:first-child{margin-top:0}
    .myst-evidence-label::after{content:"";flex:1;height:1px;background:rgba(255,45,124,.25)}
    .myst-list{list-style:none;margin:8px 0 0;padding:0}
    .myst-list li{display:flex;gap:10px;align-items:baseline;margin-bottom:8px;color:#e6d6dd;rozmiar czcionki:13,5px;wysokość linii:1,6}
    .myst-idx{
      flex:0 0 auto;rodzina czcionek:"Space Mono",ui-monospace,monospace;rozmiar czcionki:10px;
      odstępy między literami:.08em;kolor:var(--vi-gold,#ffd166);przezroczystość:.85;min-width:30px;
    }
    .myst-rozdzielczość{
      górny margines: 18 pikseli; dopełnienie: 14 pikseli 16 pikseli; promień obramowania: 10 pikseli;
      obramowanie: 1 piks. przerywana rgba (255 209 102, .6); tło: rgba (255 209 102, 07);
    }
    .myst-rozdzielczość .myst-evidence-label{color:var(--vi-gold,#ffd166);margin-top:0}
    .myst-rozdzielczość .myst-evidence-label::after{background:rgba(255,209,102,.35)}
    .myst-rozdzielczość p{margines: 8px 0 0;color:#ffe9bd;font-size:13,5px;line-height:1,62}
    .mistyczne-gdzie{
      display:flex;gap:10px;align-items:baseline;margin-top:16px;
      rodzina czcionek: „Space Mono”, ui-monospace, monospace; rozmiar czcionki: 12 pikseli;
      kolor:#cdb4c6;wysokość linii:1,55;
    }
    .myst-where svg{flex:0 0 auto;width:14px;height:14px;transform:translateY(2px);color:var(--vi-pink,#ff2d7c)}
    .myst-pusty{
      dopełnienie: 34px 26px;wyrównanie tekstu:środek;kolor:#d3a8c2;
      rodzina czcionek: „Space Mono”, ui-monospace, monospace; rozmiar czcionki: 13 pikseli; odstępy między literami: .08em;
    }
    @media (maks. szerokość: 760 pikseli){
      .myst-filterbar{flex-direction:column;align-items:stretch}
      .myst-select{width:100%}
      .myst-grid{grid-template-columns:1fr}
      .myst-card{padding:18px 16px 16px}
    }
    @media (preferuje-ograniczony-ruch:zmniejsz){
      .myst-chip,.myst-chip:hover{transform:none;transition:none}
    }
